import{z as s,x as A,o as e,c as p,q as n,j as i,D as E,d as r,s as o,S as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"合并与少数股东","description":"","frontmatter":{"title":"合并与少数股东","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/nci-consolidation.md","filePath":"quant/nci-consolidation.md","lastUpdated":1791413859000}'),B={name:"quant/nci-consolidation.md"};function d(c,a,m,D,h,C){const t=A("Mermaid");return e(),p("div",null,[a[2]||(a[2]=n('<h1 id="合并与少数股东" tabindex="-1">合并与少数股东 <a class="header-anchor" href="#合并与少数股东" aria-label="Permalink to &quot;合并与少数股东&quot;">​</a></h1><div class="epigraph"><p>合并把子公司的资产与利润全额加进来，再单独划出不属于母公司股东的一份；用错归属，ROE 与账面市值比较的就不是同一类要求权。</p><footer>—— 据 Penman 对合并报表与少数股东权益的处理；Fama–French 账面权益构造中对非控制权益的惯例整理</footer></div><p>上一课<a href="/quant/lease-off-balance">租赁与表外</a>决定哪些使用权进表。本课决定<strong>哪些主体进表</strong>：合并范围与非控制权益（少数股东）。这是财务课程最后一课。下一课起进入「市场制度、资金与事件」，对象从公司状态表换成可交易杠杆与清算规则。本课不重写租赁，也不提前讲保证金。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>控制一家子公司后，合并报表把子的资产、负债、收入、费用全额纳入，即使母公司只持有 70%。利润表划出少数股东损益，资产负债表划出少数股东权益。盈利因子若用「归属母公司净利润」配「含少数股东的总权益」，ROE 被压低；反过来，用合并净利润配母公司权益，ROE 被抬高。价值因子的账面同样要声明含不含 NCI。缺口是要求权对齐：市值通常是母公司流通股本的市值，账面与利润就应取归属母公司的那一层，除非你显式把 NCI 也当成要求权并找到对应价格——通常没有单独市值。</p><p>合并范围变化（收购、出售、VIE）会造成收入与资产跳变，投资因子再次被会计主体改变推动，类似并购商誉年。</p><p><span class="marginnote">出售子公司时若把它的历史数据从合并表里删掉以「保持连续」，等于悄悄改写过去的资产规模：资产增长因子会在出售当年看到一笔虚假的巨幅收缩，按规模排序的回测随之失真。正确做法是范围按当时报表冻结，跳变留给事件研究。</span></p><p>用一组具体数字看分子分母取错层会怎样：</p>',8)),(e(),i(l,null,{default:E(()=>[o(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%90%88%E5%B9%B6%E5%87%80%E5%88%A9%E6%B6%A6%20100%22%5D%20--%3E%20B%5B%22%E5%88%92%E5%87%BA%E5%B0%91%E6%95%B0%E8%82%A1%E4%B8%9C%E6%8D%9F%E7%9B%8A%2015%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%BD%92%E5%B1%9E%E6%AF%8D%E5%85%AC%E5%8F%B8%E5%88%A9%E6%B6%A6%2085%22%5D%0A%20%20D%5B%22%E6%9D%83%E7%9B%8A%E5%90%88%E8%AE%A1%201000%22%5D%20--%3E%20E%5B%22NCI%20%E6%9D%83%E7%9B%8A%20100%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%AF%8D%E5%85%AC%E5%8F%B8%E6%9D%83%E7%9B%8A%20900%22%5D%0A%20%20C%20--%3E%20G%5B%22%E9%85%8D%E5%AF%B9%E6%AD%A3%E7%A1%AE%EF%BC%9A85%2F900%20%E2%89%88%209.4%25%22%5D%0A%20%20F%20--%3E%20G%0A%20%20A%20--%3E%20H%5B%22%E8%AF%AF%E9%85%8D%EF%BC%9A100%2F900%20%3D%2011.1%25%EF%BC%8CROE%20%E8%A2%AB%E6%8A%AC%E9%AB%98%22%5D%0A%20%20F%20--%3E%20H%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<h3 id="少数股东权益不是负债" tabindex="-1">少数股东权益不是负债 <a class="header-anchor" href="#少数股东权益不是负债" aria-label="Permalink to &quot;少数股东权益不是负债&quot;">​</a></h3><p>NCI 是权益，不是有息债务。把它加进净负债去算杠杆，会夸大杠杆因子。把它从权益里丢掉却把子公司资产留在总资产里，投资与资产周转率失真。正确做法是全套选用「归属母公司」或全套选用「集团」，不要分子一层、分母另一层。</p><p><span class="marginnote">初学者容易以为 NCI 是「欠少数股东的钱」，顺手塞进净负债。实际上它与母公司股东同层，是对子公司净资产的权益要求；错当负债会同时夸大杠杆、错算利息保障倍数，杠杆因子里的排序被系统性改写。</span></p><p><span class="marginnote">Fama–French 账面常用归属普通股股东的权益，并处理优先股与 NCI。复制时要看说明书是否 subtract minority interest，不能只下载一个 SEQ 字段。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>来源卡上为每个因子加一行：NCI 是否进入账面、净利润是否归属母公司、总资产是否合并全额（通常是）。市值用母公司普通股市值。PIT：合并范围以当时年报/季报为准，后来出售的子公司不得从历史合并表里删掉来「保持连续」——那是另一种幸存者。范围变化在形成日作为当时事实进入资产增长。</p><p>交叉持股与库存股已在稀释、回购课处理，不在此重算，但合并层会再出现一次内部抵消；以合并后字段为准，不要把母公司单体表与合并表混接到同一时间序列。</p>',7)),(e(),i(l,null,{default:E(()=>[o(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E5%AD%90%E5%85%AC%E5%8F%B8%E5%85%A8%E9%A2%9D%E5%B9%B6%E5%85%A5%22%5D%20--%3E%20GRP%5B%22%E5%90%88%E5%B9%B6%E8%B5%84%E4%BA%A7%E4%B8%8E%E5%88%A9%E6%B6%A6%22%5D%0A%20%20GRP%20--%3E%20NCI%5B%22%E5%88%92%E5%87%BA%E5%B0%91%E6%95%B0%E8%82%A1%E4%B8%9C%22%5D%0A%20%20NCI%20--%3E%20PAR%5B%22%E5%BD%92%E5%B1%9E%E6%AF%8D%E5%85%AC%E5%8F%B8%E6%9D%83%E7%9B%8A%E4%B8%8E%E5%88%A9%E6%B6%A6%22%5D%0A%20%20PAR%20--%3E%20MV%5B%22%E9%85%8D%E6%AF%8D%E5%85%AC%E5%8F%B8%E5%B8%82%E5%80%BC%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<p>归属母公司的利润配母公司市值；总资产仍是合并全额。已售子公司不从历史合并范围擦掉。下一课保证金不再使用报表 D/E 当维持线。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>合并是控制观：经济上你指挥了 100% 的资产，会计就加总 100%，再承认别人的剩余要求权。因子若交易的是可买到的普通股，应对齐母公司股东那一层。控制观与要求权观打架时，资产增长（控制观）与 ROE（要求权观）会同时动但故事不同。这与分部课对称：分部没有独立市值，NCI 通常也没有；能交易的仍是母公司证券。财务课程在此收束：后面制度课假设你已经能交出当时可交易、口径对齐、含退市的基本面截面。</p><p><span class="marginnote">可以把 NCI 想象成合租室友：整套房的水电费都先记在你的账本上（合并收入全额并入），月底再划出室友承担的那份；写在你名下的利润与权益，才是能和你的股票市值放在一起比较的口径。</span></p><p><span class="marginnote">下一课保证金问的是经纪商如何对这份证券杠杆。合并杠杆是报表杠杆，保证金是资金约束，不要把资产负债率直接当成维持保证金。</span></p><p>价值与 ROE 默认对齐母公司普通股：利润用归属母公司，账面不含 NCI（或按说明书明确处理），市值用母公司普通股。总资产仍是合并全额，因此资产周转与 ROE 的要求权层不同，这是合法的，只要不把两者当同一杠杆叙事。出售子公司后，历史合并表保持当时范围，不要为了「连续经营」把已售业务从过去剔掉。单体表与合并表禁止混接。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写 VIE 准则全文，不做法务上的控制权鉴定。下一课<a href="/quant/margin-maintenance">保证金与维持保证金</a>换题目：可交易资金，不是会计合并。后课默认：盈利与价值已声明 NCI 口径并与母公司市值对齐；合并范围按当时报表，不事后剔出已售子公司。</p><p>下一课换成保证金：报表 D/E 不是维持保证金。财务课程在此结束，交给制度课的是一张 PIT、含退市、口径对齐、来源可指回的基本面截面。合并范围按当时报表，已售子公司不从历史里擦掉。价值与盈利的要求权层已声明并与母公司市值对齐。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>合并全额加总，再划出 NCI；分子分母必须同一层要求权。</li><li>母公司市值应对齐归属母公司的账面与利润。</li><li>NCI 是权益不是债务，不可塞进净负债。</li><li>合并范围变化按当时报表进入资产增长，不回溯「保持连续」。</li><li>财务课止于此；下一课程换资金与制度。</li><li>出处：Penman 合并与 NCI；Fama–French 账面权益构造惯例。</li></ul>',11))])}const f=s(B,[["render",d]]);export{u as __pageData,f as default};
